html:
{#
  Payment Voucher — Print Format
  App     : dux_voucher | Frappe v16 / ERPNext v16
  Module  : Dux Voucher

  HEADER FIELDS (verified from payment_voucher.json)
  doc.company, doc.posting_date, doc.mode_of_payment, doc.paid_from_account
  doc.entry_mode, doc.amount, doc.party_rows, doc.account_rows
  doc.transfer_from_account, doc.transfer_to_account
  doc.reference_no, doc.reference_date, doc.cost_center, doc.project
  doc.remarks, doc.backend_references

  PV Party Row  : party, party_type, party_name, amount
  PV Account Row: account, debit, credit, cost_center, project
  PV Backend Ref: reference_doctype, reference_name
#}

{%- set company_doc = frappe.get_doc("Company", doc.company) %}
{%- set _raw_logo   = company_doc.get("custom_voucher_print_logo") %}
{%- if _raw_logo %}
  {%- set logo_url = frappe.utils.get_url(_raw_logo) %}
{%- else %}
  {%- set logo_url = frappe.utils.get_url("/assets/dux_voucher/images/dv_logo.png") %}
{%- endif %}
{%- set entry_mode  = doc.get("entry_mode") or "Party-wise" %}
{%- set currency    = company_doc.get("default_currency") or "INR" %}
{%- set sym         = frappe.db.get_value("Currency", currency, "symbol") or "&#8377;" %}
{%- set footer_note = company_doc.get("custom_voucher_footer_note") or
    "This is a computer-generated voucher. Valid without physical stamp unless specified by policy." %}

{%- set _mop       = doc.get("mode_of_payment") or "" %}
{%- set _mop_type  = frappe.db.get_value("Mode of Payment", _mop, "type") if _mop else "" %}
{%- set _is_cheque = "cheque" in _mop.lower() %}
{%- set _is_bank   = (_mop_type == "Bank") and not _is_cheque %}

{%- if entry_mode == "Head-wise" %}
  {%- set _tns = namespace(dr=0, cr=0) %}
  {%- for _r in (doc.get("account_rows") or []) %}
    {%- set _tns.dr = _tns.dr + (_r.get("debit") or 0) %}
    {%- set _tns.cr = _tns.cr + (_r.get("credit") or 0) %}
  {%- endfor %}
  {%- set total = _tns.dr - _tns.cr %}
{%- else %}
  {%- set total = doc.get("amount") or 0 %}
{%- endif %}

{%- set _owner_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}

{%- set _je_ns = namespace(name=None) %}
{%- for ref in (doc.get("backend_references") or []) %}
  {%- if ref.get("backend_document") and ref.get("backend_doctype") == "Journal Entry" %}
    {%- set _je_ns.name = ref.backend_document %}
  {%- endif %}
{%- endfor %}

{%- set _tf_type = frappe.db.get_value("Account", doc.get("transfer_from_account"), "account_type") if doc.get("transfer_from_account") else "" %}

{%- if entry_mode == "Contra Entry" %}
  {%- set _meta_mop  = "Bank Transfer" if _tf_type == "Bank" else "Cash Transfer" %}
  {%- set _meta_from = doc.get("transfer_from_account") or "—" %}
{%- else %}
  {%- set _meta_mop  = _mop or "—" %}
  {%- set _meta_from = doc.get("paid_from_account") or "—" %}
{%- endif %}

{%- set _ref_no_label   = "Cheque No." if _is_cheque else ("UTR No." if _is_bank else "Reference No.") %}
{%- set _ref_date_label = "Cheque Date" if _is_cheque else "Reference Date" %}
{%- set _show_ref = doc.get("reference_no") or doc.get("reference_date") or doc.get("cost_center") or doc.get("project") or entry_mode in ("Head-wise", "Contra Entry") %}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Payment Voucher — {{ doc.name }}</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 12px; color: #1a1a2e; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .page { width: 100%; max-width: 210mm; margin: 0 auto; padding: 5mm 8mm 6mm; display: flex; flex-direction: column; gap: 0; }
  .header { display: grid; grid-template-columns: 90px 1fr 155px; gap: 10px; align-items: flex-start; padding-bottom: 10px; border-bottom: 2.5px solid #3C3489; }
  .logo-wrap img { width: 82px; height: auto; max-height: 52px; object-fit: contain; display: block; }
  .co-name { font-size: 14px; font-weight: 700; color: #3C3489; margin-bottom: 4px; }
  .co-meta { font-size: 9.5px; color: #555; line-height: 1.65; }
  .doc-title-block { text-align: right; }
  .vch-label { font-size: 13px; font-weight: 700; color: #3C3489; letter-spacing: 1px; text-transform: uppercase; }
  .doc-no-pill { display: inline-block; margin-top: 5px; background: #EEEDFE; color: #26215C; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 4px; }
  .date-label { font-size: 8.5px; color: #888; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 7px; }
  .date-value { font-size: 12px; font-weight: 600; color: #1a1a2e; margin-top: 2px; }
  .meta-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #ccc9e8; border-top: none; }
  .mc { padding: 7px 11px; border-right: 0.5px solid #ccc9e8; }
  .mc:last-child { border-right: none; }
  .mc-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #888; margin-bottom: 3px; }
  .mc-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }
  .badge { display: inline-block; font-size: 9px; font-weight: 700; padding: 2px 8px; border-radius: 20px; vertical-align: middle; }
  .b-party { background: #EEEDFE; color: #3C3489; }
  .b-head  { background: #E1F5EE; color: #0F6E56; }
  .b-contra{ background: #FAEEDA; color: #854F0B; }
  .b-sup   { background: #E6F1FB; color: #185FA5; }
  .b-cust  { background: #EAF3DE; color: #3B6D11; }
  .b-emp   { background: #FAECE7; color: #993C1D; }
  .sec-title { background: #f4f3fc; border-top: 0.5px solid #ccc9e8; border-bottom: 0.5px solid #ccc9e8; padding: 5px 11px; font-size: 8.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.7px; color: #3C3489; margin-top: 6px; }
  table.t { width: 100%; border-collapse: collapse; border: 0.5px solid #ccc9e8; border-top: none; }
  table.t th { background: #f9f8fe; font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; color: #555; padding: 6px 11px; border-bottom: 0.5px solid #ccc9e8; border-right: 0.5px solid #ccc9e8; text-align: left; white-space: nowrap; }
  table.t th:last-child { border-right: none; }
  table.t th.r { text-align: right; }
  table.t td { padding: 7px 11px; border-bottom: 0.5px solid #eeeef8; border-right: 0.5px solid #eeeef8; vertical-align: middle; font-size: 11px; color: #1a1a2e; }
  table.t td:last-child { border-right: none; }
  table.t tr:last-child td { border-bottom: none; }
  table.t td.r { text-align: right; font-variant-numeric: tabular-nums; font-family: 'Courier New', monospace; font-size: 11.5px; white-space: nowrap; }
  table.t td.ctr { text-align: center; width: 28px; color: #aaa; font-size: 10px; }
  .pname { font-weight: 600; font-size: 11px; }
  .psub  { font-size: 9.5px; color: #888; margin-top: 2px; }
  .pamt  { font-size: 12px; font-weight: 700; }
  .ref-row { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; border: 0.5px solid #ccc9e8; border-top: none; }
  .ref-cell { padding: 6px 11px; border-right: 0.5px solid #ccc9e8; }
  .ref-cell:last-child { border-right: none; }
  .ref-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; }
  .ref-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }
  .totals-bar { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border: 0.5px solid #ccc9e8; border-top: 1.5px solid #3C3489; background: #f9f8fe; margin-top: 6px; }
  .w-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .w-value { font-size: 10.5px; font-style: italic; color: #3C3489; font-weight: 600; max-width: 320px; }
  .a-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; text-align: right; }
  .a-value { font-size: 21px; font-weight: 700; color: #3C3489; text-align: right; }
  .remarks-block { border: 0.5px solid #ccc9e8; border-top: none; padding: 7px 11px; }
  .r-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .r-value { font-size: 11px; color: #333; line-height: 1.5; }
  .bk-refs { border: 0.5px solid #ccc9e8; border-top: none; padding: 6px 11px; background: #f9f8fe; }
  .bk-ref-row { display: flex; gap: 20px; flex-wrap: wrap; }
  .bk-ref-item { font-size: 10px; color: #444; }
  .bk-ref-item span { color: #3C3489; font-weight: 600; }
  .sig-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #ccc9e8; margin-top: 14px; }
  .sig-cell { padding: 7px 14px 9px; border-right: 0.5px solid #ccc9e8; text-align: center; }
  .sig-cell:last-child { border-right: none; }
  .sig-space { height: 34px; }
  .sig-line { border-top: 1px solid #3C3489; margin-bottom: 4px; }
  .sig-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #555; }
  .sig-name  { font-size: 9px; color: #3C3489; font-weight: 600; margin-top: 2px; }
  .page-footer { margin-top: 10px; padding-top: 8px; border-top: 0.5px solid #ccc9e8; display: flex; justify-content: space-between; align-items: center; }
  .page-footer .note { font-size: 8.5px; color: #aaa; font-style: italic; max-width: 480px; }
  .page-footer .brand { font-size: 8.5px; color: #aaa; white-space: nowrap; }
  .page-footer .brand strong { color: #3C3489; }
  @media print {
    body { background: white; }
    .page { padding: 3mm 5mm; margin: 0; width: 100%; max-width: 100%; }
    @page { size: A4; margin: 10mm; }
  }
</style>
</head>
<body>
<div class="page">

  <div class="header">
    <div class="logo-wrap">
      <img src="{{ logo_url }}" alt="{{ company_doc.company_name or doc.company }}">
    </div>
    <div>
      <div class="co-name">{{ company_doc.company_name or doc.company }}</div>
      <div class="co-meta">
        {%- if company_doc.get("gstin") %}GSTIN: {{ company_doc.gstin }}{%- if company_doc.get("tax_id") %} &nbsp;|&nbsp; PAN: {{ company_doc.tax_id }}{%- endif %}<br>{%- elif company_doc.get("tax_id") %}PAN: {{ company_doc.tax_id }}<br>{%- endif %}
        {%- if company_doc.get("phone_no") %}Ph: {{ company_doc.phone_no }}{%- endif %}{%- if company_doc.get("phone_no") and company_doc.get("email") %} &nbsp;|&nbsp; {%- endif %}{%- if company_doc.get("email") %}{{ company_doc.email }}{%- endif %}
      </div>
    </div>
    <div class="doc-title-block">
      <div class="vch-label">Payment Voucher</div>
      <div><span class="doc-no-pill">{{ doc.name }}</span></div>
      <div class="date-label">Date</div>
      <div class="date-value">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>
    </div>
  </div>

  <div class="meta-strip">
    <div class="mc">
      <div class="mc-label">Payment Method</div>
      <div class="mc-value">{{ _meta_mop }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Paid From Account</div>
      <div class="mc-value">{{ _meta_from }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Entry Type</div>
      <div class="mc-value">
        {%- if entry_mode == "Party-wise" %}<span class="badge b-party">Party-wise</span>
        {%- elif entry_mode == "Head-wise" %}<span class="badge b-head">Head-wise</span>
        {%- else %}<span class="badge b-contra">Contra Entry</span>
        {%- endif %}
      </div>
    </div>
  </div>

  {%- if entry_mode == "Party-wise" %}
  <div class="sec-title">Payment Details &#8212; Party-wise</div>
  <table class="t">
    <thead><tr>
      <th class="ctr" style="width:28px;">S.No.</th>
      <th>Party</th>
      <th class="r" style="width:120px;">Amount ({{ sym }})</th>
    </tr></thead>
    <tbody>
      {%- for row in (doc.get("party_rows") or []) %}
      <tr>
        <td class="ctr">{{ loop.index }}</td>
        <td>
          <span class="pname">{{ row.get("party_name") or row.party or "&#8212;" }}</span>
          {%- if row.get("party_type") == "Supplier" %}&nbsp;<span class="badge b-sup">Supplier</span>
          {%- elif row.get("party_type") == "Customer" %}&nbsp;<span class="badge b-cust">Customer</span>
          {%- elif row.get("party_type") == "Employee" %}&nbsp;<span class="badge b-emp">Employee</span>
          {%- endif %}
          {%- if row.get("party_name") and row.party_name != row.party %}<div class="psub">{{ row.party }}</div>{%- endif %}
        </td>
        <td class="r pamt">{{ frappe.utils.fmt_money(row.get("amount") or 0, currency=currency) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  {%- elif entry_mode == "Head-wise" %}
  <div class="sec-title">Payment Details &#8212; Account / Head-wise</div>
  <table class="t">
    <thead><tr>
      <th class="ctr" style="width:28px;">S.No.</th>
      <th>Account / Head</th>
      <th class="r" style="width:100px;">Debit ({{ sym }})</th>
      <th class="r" style="width:100px;">Credit ({{ sym }})</th>
    </tr></thead>
    <tbody>
      {%- if _je_ns.name %}
        {%- set _je = frappe.get_doc("Journal Entry", _je_ns.name) %}
        {%- for row in _je.accounts %}
        <tr>
          <td class="ctr">{{ loop.index }}</td>
          <td><span class="pname">{{ row.account or "&#8212;" }}</span></td>
          <td class="r pamt">
            {%- set _d = row.get("debit_in_account_currency") or row.get("debit") or 0 %}
            {{ frappe.utils.fmt_money(_d, currency=currency) if _d > 0 else "" }}
          </td>
          <td class="r pamt">
            {%- set _c = row.get("credit_in_account_currency") or row.get("credit") or 0 %}
            {{ frappe.utils.fmt_money(_c, currency=currency) if _c > 0 else "" }}
          </td>
        </tr>
        {%- endfor %}
      {%- else %}
        {%- for row in (doc.get("account_rows") or []) %}
        <tr>
          <td class="ctr">{{ loop.index }}</td>
          <td><span class="pname">{{ row.get("account") or "&#8212;" }}</span></td>
          <td class="r pamt">{{ frappe.utils.fmt_money(row.debit, currency=currency) if row.get("debit") and row.debit > 0 else "" }}</td>
          <td class="r pamt">{{ frappe.utils.fmt_money(row.credit, currency=currency) if row.get("credit") and row.credit > 0 else "" }}</td>
        </tr>
        {%- endfor %}
      {%- endif %}
    </tbody>
  </table>

  {%- elif entry_mode == "Contra Entry" %}
  <div class="sec-title">Payment Details &#8212; Contra / Internal Transfer</div>
  <table class="t">
    <thead><tr>
      <th style="width:45%;">Transfer From</th>
      <th style="width:10%; text-align:center;"></th>
      <th style="width:45%;">Transfer To</th>
    </tr></thead>
    <tbody>
      <tr>
        <td><span class="pname" style="color:#3C3489;">{{ doc.get("transfer_from_account") or "&#8212;" }}</span></td>
        <td style="text-align:center; font-size:16px; color:#854F0B; font-weight:700;">&#8594;</td>
        <td><span class="pname" style="color:#0F6E56;">{{ doc.get("transfer_to_account") or "&#8212;" }}</span></td>
      </tr>
    </tbody>
  </table>
  {%- endif %}

  {%- if _show_ref %}
  <div class="ref-row">
    <div class="ref-cell">
      <div class="ref-label">{{ _ref_no_label }}</div>
      <div class="ref-value">{{ doc.get("reference_no") or "&#8212;" }}</div>
    </div>
    <div class="ref-cell">
      <div class="ref-label">{{ _ref_date_label }}</div>
      <div class="ref-value">
        {%- if doc.get("reference_date") %}{{ frappe.format(doc.reference_date, {"fieldtype": "Date"}) }}{%- else %}&#8212;{%- endif %}
      </div>
    </div>
    <div class="ref-cell">
      <div class="ref-label">Cost Centre</div>
      <div class="ref-value">{{ doc.get("cost_center") or "&#8212;" }}</div>
    </div>
    <div class="ref-cell">
      <div class="ref-label">Project</div>
      <div class="ref-value">{{ doc.get("project") or "&#8212;" }}</div>
    </div>
  </div>
  {%- endif %}

  <div class="totals-bar">
    <div>
      <div class="w-label">Amount in words</div>
      <div class="w-value">
        {%- set _words = frappe.utils.money_in_words(total, main_currency=currency) or "&#8212;" %}
        {{ _words.replace("INR ", "").replace("USD ", "").replace("EUR ", "") if _words != "&#8212;" else "&#8212;" }}
      </div>
    </div>
    <div>
      <div class="a-label">Total Amount</div>
      <div class="a-value">{{ frappe.utils.fmt_money(total, currency=currency) }}</div>
    </div>
  </div>

  {%- if doc.get("remarks") %}
  <div class="remarks-block">
    <div class="r-label">Remarks / Narration</div>
    <div class="r-value">{{ doc.remarks }}</div>
  </div>
  {%- endif %}



  <div class="sig-strip">
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Prepared By</div>
      <div class="sig-name">{{ _owner_name }}</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Verified By</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Authorised Signatory</div>
    </div>
  </div>

  <div class="page-footer">
    <div class="note">{{ footer_note }}</div>
    <div class="brand">Powered by <strong>DUX DigiTech</strong></div>
  </div>

</div>
</body>
</html>
